def candidate(x):
    m = jnp.max(x, axis=-1, keepdims=True)
    e = jnp.exp(x - m)
    return e * jax.lax.reciprocal(jnp.sum(e, axis=-1, keepdims=True))

import jax
import jax.numpy as jnp

def candidate(x, w, b, gamma, beta):
    eps = jnp.float32(1e-5)

    def row_fn(xrow):
        h = jnp.matmul(xrow, w) + b
        z = h * jnp.float32(0.5) * jax.lax.erfc(-h * jnp.float32(0.707106769))
        mean = jnp.mean(z)
        centered = z - mean
        var = jnp.mean(centered * centered)
        return centered * jax.lax.rsqrt(var + eps) * gamma + beta

    return jax.lax.map(row_fn, x)

